$qitonifyherbs = [
    ['name'=>'Ren Shen','latin'=>'Ginseng Radix et Rhizoma','properties'=>$qitonifytext('Sweet, slightly bitter; slightly warm','Dulce, ligeramente amarga; ligeramente tibia'),'channels'=>$qitonifytext('Lung, Spleen, Heart','Pulmón, Bazo, Corazón'),'dose'=>'1.5–9 g','identity'=>$qitonifytext('Powerfully tonifies Original Qi, rescues collapse, strengthens Spleen and Lung, generates fluids and calms Shen.','Tonifica con fuerza Qi Original, rescata colapso, fortalece Bazo y Pulmón, genera líquidos y calma Shen.'),'clue'=>$qitonifytext('Severe or multisystem Qi deficiency, weak breath and pulse, profuse sweating or thirst after major fluid loss.','Deficiencia grave o multisistémica de Qi, respiración y pulso débiles, sudor profuso o sed tras gran pérdida de líquidos.'),'memory'=>$qitonifytext('The emperor restores power to the entire Qi palace.','El emperador restaura energía a todo el palacio del Qi.'),'unique'=>$qitonifytext('Yang ranks it 100 for general Qi, Lung-Qi and Spleen-Qi—the strongest and fastest herb in the current group.','Yang le asigna 100 para Qi general, Qi de Pulmón y Qi de Bazo—la más fuerte y rápida del grupo actual.'),'caution'=>$qitonifytext('Strong and somewhat cloying; avoid indiscriminate use with Excess, acute pathogen, food stagnation or severe Dampness. May interact with medications.','Fuerte y algo empalagosa; evitar uso indiscriminado con Exceso, patógeno agudo, estancamiento alimentario o Humedad grave. Puede interactuar con medicamentos.'),'formulas'=>[[32,'si-jun-zi-tang','Si Jun Zi Tang',$qitonifytext('chief','principal')],[34,'sheng-mai-san','Sheng Mai San',$qitonifytext('co-chief','coprincipal')],[36,'gui-pi-tang','Gui Pi Tang',$qitonifytext('co-chief','coprincipal')],[37,'shi-quan-da-bu-tang','Shi Quan Da Bu Tang',$qitonifytext('co-chief','coprincipal')]]],
    ['name'=>'Dang Shen','latin'=>'Codonopsis Radix','properties'=>$qitonifytext('Sweet; neutral','Dulce; neutra'),'channels'=>$qitonifytext('Lung, Spleen','Pulmón, Bazo'),'dose'=>'9–30 g','identity'=>$qitonifytext('Gently tonifies Spleen and Lung Qi, supports Blood generation and produces fluids without the heaviness of Ren Shen.','Tonifica suavemente Qi de Bazo y Pulmón, apoya generación de Sangre y produce líquidos sin la pesadez de Ren Shen.'),'clue'=>$qitonifytext('Chronic fatigue, poor appetite, loose stool and weak voice when strong emergency tonification is unnecessary.','Fatiga crónica, poco apetito, heces sueltas y voz débil cuando no hace falta tonificación urgente fuerte.'),'memory'=>$qitonifytext('The dependable deputy handles daily chronic Qi work.','La suplente confiable realiza el trabajo diario del Qi crónico.'),'unique'=>$qitonifytext('Yang gives it 60 for general, Lung and Spleen Qi. It may substitute for Ren Shen in ordinary chronic deficiency, but not collapse.','Yang le da 60 para Qi general, de Pulmón y de Bazo. Puede sustituir Ren Shen en deficiencia crónica común, pero no en colapso.'),'caution'=>$qitonifytext('Still sweet and tonifying; use cautiously with unresolved Exterior disease, strong Excess or marked food/Damp accumulation.','Aun es dulce y tónica; cautela con enfermedad Exterior no resuelta, Exceso fuerte o acumulación marcada de alimento/Humedad.'),'formulas'=>[]],
    ['name'=>'Huang Qi','latin'=>'Astragali Radix','properties'=>$qitonifytext('Sweet; slightly warm','Dulce; ligeramente tibia'),'channels'=>$qitonifytext('Lung, Spleen','Pulmón, Bazo'),'dose'=>'9–30 g','identity'=>$qitonifytext('Tonifies and raises Spleen Qi, strengthens Defensive Qi, stabilizes the Exterior, promotes healing and regulates water.','Tonifica y eleva Qi de Bazo, fortalece Qi Defensivo, estabiliza Exterior, promueve cicatrización y regula agua.'),'clue'=>$qitonifytext('Spontaneous sweating or recurrent colds, prolapse, chronic nonhealing sores, Qi-deficiency bleeding or edema.','Sudor espontáneo o resfriados recurrentes, prolapso, llagas crónicas sin cerrar, sangrado por deficiencia de Qi o edema.'),'memory'=>$qitonifytext('The yellow shield raises the walls, closes the gates and lifts what has fallen.','El escudo amarillo eleva murallas, cierra puertas y levanta lo caído.'),'unique'=>$qitonifytext('Yang gives it 70 across general, Lung and Spleen Qi. Unlike Ren Shen, its signature is outward/ascending: Exterior, muscles, prolapse and wounds.','Yang le da 70 en Qi general, Pulmón y Bazo. A diferencia de Ren Shen, su firma es exterior/ascendente: Exterior, músculos, prolapso y heridas.'),'caution'=>$qitonifytext('Do not trap an active Exterior pathogen or unresolved toxic swelling. Use carefully with Yin deficiency Heat or strong Qi stagnation.','No encerrar patógeno Exterior activo ni hinchazón tóxica no resuelta. Cautela con Calor por deficiencia de Yin o estancamiento fuerte de Qi.'),'formulas'=>[[33,'bu-zhong-yi-qi-tang','Bu Zhong Yi Qi Tang',$qitonifytext('chief','principal')],[36,'gui-pi-tang','Gui Pi Tang',$qitonifytext('co-chief','coprincipal')],[49,'yu-ping-feng-san','Yu Ping Feng San',$qitonifytext('chief','principal')]]],
    ['name'=>'Gan Cao','latin'=>'Glycyrrhizae Radix et Rhizoma','properties'=>$qitonifytext('Sweet; neutral (raw), slightly warm (prepared)','Dulce; neutra (cruda), ligeramente tibia (preparada)'),'channels'=>$qitonifytext('Heart, Lung, Spleen, Stomach; all channels','Corazón, Pulmón, Bazo, Estómago; todos los canales'),'dose'=>'2–10 g','identity'=>$qitonifytext('Moderately tonifies Qi, moistens Lung, stops spasm and pain, clears toxicity when raw and harmonizes formulas.','Tonifica Qi moderadamente, humedece Pulmón, detiene espasmo/dolor, aclara toxicidad cruda y armoniza fórmulas.'),'clue'=>$qitonifytext('Qi deficiency needing harmonization, weak Heart Qi with irregular pulse, spasm or harsh-herb moderation.','Deficiencia de Qi que necesita armonización, Qi de Corazón débil con pulso irregular, espasmo o moderación de hierbas agresivas.'),'memory'=>$qitonifytext('The diplomat sweetens disputes and keeps every formula moving together.','La diplomática endulza disputas y mantiene unida toda la fórmula.'),'unique'=>$qitonifytext('Yang ranks its Qi tonification at 30: weaker than the main tonics, but unmatched for harmonizing, moderating and reaching every channel.','Yang coloca su tonificación de Qi en 30: más débil que las tónicas principales, pero incomparable para armonizar, moderar y alcanzar todos los canales.'),'caution'=>$qitonifytext('Excess or prolonged intake can cause sodium/water retention, hypertension, low potassium and arrhythmia; major medication interactions are possible.','Exceso o uso prolongado puede causar retención de sodio/agua, hipertensión, potasio bajo y arritmia; puede tener interacciones medicamentosas importantes.'),'formulas'=>[[36,'gui-pi-tang','Gui Pi Tang',$qitonifytext('co-chief','coprincipal')]]],
    ['name'=>'Bai Zhu','latin'=>'Atractylodis Macrocephalae Rhizoma','properties'=>$qitonifytext('Bitter, sweet; warm','Amarga, dulce; tibia'),'channels'=>$qitonifytext('Spleen, Stomach','Bazo, Estómago'),'dose'=>'6–12 g','identity'=>$qitonifytext('Tonifies Spleen Qi while drying Dampness, stops sweating and diarrhea and calms a fetus disturbed by Spleen deficiency.','Tonifica Qi de Bazo mientras seca Humedad, detiene sudor/diarrea y calma feto alterado por deficiencia de Bazo.'),'clue'=>$qitonifytext('Poor appetite and fatigue with abdominal fullness, loose stool, edema or heaviness from Spleen-Qi deficiency plus Dampness.','Poco apetito y fatiga con plenitud abdominal, heces sueltas, edema o pesadez por deficiencia de Qi de Bazo más Humedad.'),'memory'=>$qitonifytext('The dry pantry manager strengthens the kitchen and removes its damp mold.','La encargada de la despensa seca fortalece cocina y elimina su moho húmedo.'),'unique'=>$qitonifytext('Yang gives it 50 for general/Spleen Qi. Raw emphasizes tonification, dry-fried emphasizes drying and diarrhea, deep-fried emphasizes Stomach reception.','Yang le da 50 para Qi general/de Bazo. Cruda enfatiza tonificar, salteada secar/diarrea y muy tostada recepción de Estómago.'),'caution'=>$qitonifytext('Warm and drying; use cautiously with Yin/fluid deficiency, dry thirst or constipation without Dampness.','Tibia y secante; cautela con deficiencia de Yin/líquidos, sed seca o estreñimiento sin Humedad.'),'formulas'=>[[36,'gui-pi-tang','Gui Pi Tang',$qitonifytext('co-chief','coprincipal')]]],
    ['name'=>'Da Zao','latin'=>'Jujubae Fructus','properties'=>$qitonifytext('Sweet; warm','Dulce; tibia'),'channels'=>$qitonifytext('Spleen, Stomach','Bazo, Estómago'),'dose'=>$qitonifytext('3–12 fruits','3–12 frutos'),'identity'=>$qitonifytext('Gently tonifies Middle Qi, nourishes Blood, calms Shen and harmonizes harsh ingredients.','Tonifica suavemente Qi del Medio, nutre Sangre, calma Shen y armoniza ingredientes agresivos.'),'clue'=>$qitonifytext('Mild Spleen-Qi and Blood deficiency with fatigue, poor appetite, irritability or need to protect the Middle.','Deficiencia leve de Qi de Bazo y Sangre con fatiga, poco apetito, irritabilidad o necesidad de proteger el Medio.'),'memory'=>$qitonifytext('The red date is the comforting guest snack that protects and harmonizes the household.','El dátil rojo es la merienda reconfortante que protege y armoniza la casa.'),'unique'=>$qitonifytext('Yang gives it 20 for Spleen Qi, the gentlest current-list tonic; unlike Bai Zhu, it nourishes Blood and does not dry Dampness.','Yang le da 20 para Qi de Bazo, la tónica más suave de la lista; a diferencia de Bai Zhu, nutre Sangre y no seca Humedad.'),'caution'=>$qitonifytext('Sweet and cloying; avoid large amounts with Dampness, food stagnation, Phlegm, abdominal distension or dental/metabolic concerns.','Dulce y empalagosa; evitar grandes cantidades con Humedad, estancamiento alimentario, Flema, distensión o problemas dentales/metabólicos.'),'formulas'=>[]],
    ['name'=>'Shan Yao','latin'=>'Dioscoreae Rhizoma','properties'=>$qitonifytext('Sweet; neutral','Dulce; neutra'),'channels'=>$qitonifytext('Spleen, Lung, Kidney','Bazo, Pulmón, Riñón'),'dose'=>'9–30 g','identity'=>$qitonifytext('Gently tonifies and stabilizes both Qi and Yin of Spleen, Lung and Kidney; binds leakage.','Tonifica y estabiliza suavemente Qi y Yin de Bazo, Pulmón y Riñón; contiene pérdidas.'),'clue'=>$qitonifytext('Chronic loose stool with thirst or wasting, weak Lung, or Kidney leakage such as spermatorrhea or vaginal discharge.','Heces sueltas crónicas con sed o emaciación, Pulmón débil o pérdidas de Riñón como espermatorrea o leucorrea.'),'memory'=>$qitonifytext('The mountain yam braces three floors—Spleen, Lung and Kidney—without heating or drying.','El ñame de montaña sostiene tres pisos—Bazo, Pulmón y Riñón—sin calentar ni secar.'),'unique'=>$qitonifytext('Yang gives it 40 for general/Spleen Qi. It is the group’s neutral Qi–Yin bridge and adds astringent stabilization.','Yang le da 40 para Qi general/de Bazo. Es el puente neutro Qi–Yin del grupo y añade estabilización astringente.'),'caution'=>$qitonifytext('Its astringency may retain an active pathogen, food stagnation or substantial Dampness; differentiate before binding.','Su astringencia puede retener patógeno activo, estancamiento alimentario o Humedad importante; diferenciar antes de contener.'),'formulas'=>[]],
    ['name'=>'Yi Tang','latin'=>'Maltosum','properties'=>$qitonifytext('Sweet; warm','Dulce; tibia'),'channels'=>$qitonifytext('Spleen, Stomach, Lung','Bazo, Estómago, Pulmón'),'dose'=>$qitonifytext('30–60 g; dissolve in strained decoction','30–60 g; disolver en la decocción colada'),'identity'=>$qitonifytext('Tonifies the Middle, relieves spasmodic abdominal pain and moistens Lung cough.','Tonifica el Medio, alivia dolor abdominal espasmódico y humedece tos de Pulmón.'),'clue'=>$qitonifytext('Deficiency-Cold abdominal pain relieved by warmth, pressure and food; or dry cough without abundant Phlegm.','Dolor abdominal por Frío-deficiencia aliviado por calor, presión y comida; o tos seca sin Flema abundante.'),'memory'=>$qitonifytext('Warm malt syrup coats the empty kitchen and relaxes its painful cramp.','El jarabe tibio de malta cubre la cocina vacía y relaja su calambre doloroso.'),'unique'=>$qitonifytext('Yang gives it 20 for Spleen Qi. It is the only syrup-like food medicine here and the clearest pain-relieving Middle tonic.','Yang le da 20 para Qi de Bazo. Es la única medicina alimentaria tipo jarabe y la tónica del Medio con pista más clara de aliviar dolor.'),'caution'=>$qitonifytext('Avoid with Damp-Heat, Phlegm, vomiting, marked abdominal fullness or when concentrated sugars are inappropriate.','Evitar con Humedad-Calor, Flema, vómito, plenitud abdominal marcada o cuando azúcares concentrados no sean apropiados.'),'formulas'=>[]],
];

