$qitonifyquestions = [
    [$qitonifytext('What are the functions and indications of tonifying herbs, and what precautions should be observed?','¿Cuáles son las funciones e indicaciones de las hierbas tónicas y qué precauciones deben observarse?'),$qitonifytext('They strengthen Deficiency of Qi, Blood, Yin or Yang. Confirm true deficiency first: rich sweet herbs can trap Exterior pathogens, Phlegm, food, water or Blood/Qi stagnation and can burden a weak Middle Jiao.','Fortalecen deficiencia de Qi, Sangre, Yin o Yang. Confirma deficiencia verdadera: hierbas dulces/ricas pueden atrapar patógenos Exteriores, Flema, alimento, agua o estasis de Sangre/Qi y cargar un Jiao Medio débil.')],
    [$qitonifytext('What are direct and indirect tonification?','¿Qué son la tonificación directa e indirecta?'),$qitonifytext('Direct tonification treats the deficient substance or organ itself. Indirect tonification uses organ-generation and Qi–Blood/Yin–Yang relationships: for example, strengthen Spleen Qi with Huang Qi and Bai Zhu so Earth generates Lung Metal.','La directa trata la sustancia u órgano deficiente. La indirecta usa relaciones de generación orgánica y Qi–Sangre/Yin–Yang: por ejemplo, fortalecer Bazo con Huang Qi y Bai Zhu para que Tierra genere Metal de Pulmón.')],
    [$qitonifytext('What is the “school of tonifying the Spleen”?','¿Qué propone la “escuela de tonificar el Bazo”?'),$qitonifytext('It treats Spleen-Stomach as the Post-Heaven foundation that generates and transports Qi, Blood and fluids. Supporting the Middle can improve the whole constitution and supply other organs.','Considera Bazo-Estómago la base Posnatal que genera y transporta Qi, Sangre y líquidos. Apoyar el Medio puede mejorar toda la constitución y abastecer otros órganos.')],
    [$qitonifytext('What is the “school of tonifying the Kidney”?','¿Qué propone la “escuela de tonificar el Riñón”?'),$qitonifytext('It treats Kidney Essence, Yin and Yang as the Pre-Heaven root of life and uses long-term protection and balanced Yin–Yang support. This framework belongs mainly to later tonic categories, not to interchangeable use of these Qi tonics.','Considera Esencia, Yin y Yang de Riñón la raíz Prenatal y usa protección prolongada y apoyo equilibrado Yin–Yang. Pertenece sobre todo a categorías tónicas posteriores, no al uso intercambiable de estas tónicas de Qi.')],
    [$qitonifytext('What is the difference between strong and gentle tonification?','¿Cuál es la diferencia entre tonificación fuerte y suave?'),$qitonifytext('Strong tonification uses powerful herbs or large doses for severe deficiency; Ren Shen and Huang Qi are examples. Gentle tonification builds chronic deficiency gradually with herbs such as Dang Shen and Bai Zhu and is often better tolerated.','La fuerte usa hierbas potentes o dosis grandes para deficiencia grave; Ren Shen y Huang Qi son ejemplos. La suave construye deficiencia crónica gradualmente con Dang Shen y Bai Zhu y suele tolerarse mejor.')],
    [$qitonifytext('What are the indications for herbs that tonify Qi?','¿Cuáles son las indicaciones de las hierbas que tonifican Qi?'),$qitonifytext('General Qi deficiency causes fatigue, weak voice, poor endurance, easy illness, pale flabby tongue and weak pulse. Spleen deficiency adds poor appetite and loose stool; Lung deficiency adds short breath and spontaneous sweat; organ-specific clues guide the final choice.','Deficiencia general causa fatiga, voz débil, poca resistencia, enfermedad fácil, lengua pálida flácida y pulso débil. Bazo añade poco apetito/heces sueltas; Pulmón añade disnea/sudor espontáneo; pistas del órgano guían la elección.')],
    [$qitonifytext('What are the characteristics of herbs that tonify Qi?','¿Cuáles son las características de las hierbas que tonifican Qi?'),$qitonifytext('Most are sweet, neutral to slightly warm and enter Spleen and Lung. Sweetness nourishes and harmonizes; gentle warmth activates without consuming Qi; bitter warmth in Bai Zhu dries Dampness. Their richness can cause fullness and stagnation.','La mayoría son dulces, neutras a ligeramente tibias y entran en Bazo/Pulmón. Dulzor nutre/armoniza; calor suave activa sin consumir Qi; amargor tibio de Bai Zhu seca Humedad. Su riqueza puede causar plenitud/estancamiento.')],
    [$qitonifytext('What distinguishes Ren Shen and Huang Qi?','¿Qué distingue Ren Shen y Huang Qi?'),$qitonifytext('Ren Shen strongly restores Original Qi, generates fluids and treats collapse or broad organ deficiency. Huang Qi focuses on Spleen-Lung, raises sinking Qi, strengthens Defensive Qi/Exterior, controls sweating, moves water and promotes wound healing.','Ren Shen restaura Qi Original, genera líquidos y trata colapso o deficiencia amplia. Huang Qi se enfoca en Bazo-Pulmón, eleva Qi hundido, fortalece Qi Defensivo/Exterior, controla sudor, mueve agua y cicatriza.')],
    [$qitonifytext('How do the main Ren Shen products differ?','¿Cómo se diferencian los principales productos de Ren Shen?'),$qitonifytext('Yang ranks wild Ye Shan Shen strongest; Korean and red products are warmer, raw-dried Sheng Shai Shen balances Qi and Yin, and white root is gentler. Product identity matters; these forms should not be treated as identical.','Yang coloca Ye Shan Shen silvestre como más fuerte; productos coreanos/rojos son más tibios, Sheng Shai Shen seca equilibra Qi-Yin y raíz blanca es más suave. La identidad del producto importa; no son idénticos.')],
    [$qitonifytext('How do Xi Yang Shen, Sheng Shai Shen, Tai Zi Shen and Bei Sha Shen differ?','¿Cómo se diferencian Xi Yang Shen, Sheng Shai Shen, Tai Zi Shen y Bei Sha Shen?'),$qitonifytext('All are outside the exact list except Sheng Shai Shen as a Ren Shen product. Xi Yang Shen strongly tonifies Qi-Yin and clears Heat; Sheng Shai Shen is neutral and strong without clearing Fire; Tai Zi Shen is gentle; Bei Sha Shen mainly nourishes Lung-Stomach Yin.','Todas están fuera de la lista exacta salvo Sheng Shai Shen como producto de Ren Shen. Xi Yang Shen tonifica Qi-Yin y aclara Calor; Sheng Shai Shen es neutra/fuerte sin aclarar Fuego; Tai Zi Shen es suave; Bei Sha Shen nutre sobre todo Yin de Pulmón-Estómago.')],
    [$qitonifytext('What are the differences between Ren Shen and Dang Shen?','¿Cuáles son las diferencias entre Ren Shen y Dang Shen?'),$qitonifytext('Ren Shen is stronger, faster and restores Original Qi, so it is required for collapse. Dang Shen is neutral, gentler, less cloying and better for long-term Spleen-Lung deficiency; it cannot replace Ren Shen in critical collapse.','Ren Shen es más fuerte/rápida y restaura Qi Original, necesaria en colapso. Dang Shen es neutra, suave, menos empalagosa y mejor a largo plazo para Bazo-Pulmón; no reemplaza Ren Shen en colapso crítico.')],
    [$qitonifytext('How do Huang Qi and Bai Zhu differ?','¿Cómo se diferencian Huang Qi y Bai Zhu?'),$qitonifytext('Huang Qi tonifies more strongly, raises Spleen Qi, strengthens Lung/Exterior, treats prolapse, sweat, wounds and upper edema. Bai Zhu is weaker but dries Middle-Jiao Dampness, improves digestion, stops diarrhea and can calm a fetus from Spleen deficiency.','Huang Qi tonifica más, eleva Qi de Bazo, fortalece Pulmón/Exterior y trata prolapso, sudor, heridas y edema superior. Bai Zhu es más débil pero seca Humedad del Medio, mejora digestión, detiene diarrea y calma feto por deficiencia de Bazo.')],
    [$qitonifytext('How do raw, dry-fried and deep-dry-fried Bai Zhu differ?','¿Cómo se diferencian Bai Zhu cruda, salteada y muy tostada?'),$qitonifytext('Raw Bai Zhu most strongly tonifies Spleen Qi. Dry-fried Bai Zhu emphasizes drying Dampness and stopping loose stool. Deep-dry-fried Jiao Bai Zhu emphasizes Stomach reception, nausea, fullness and belching.','Bai Zhu cruda tonifica Bazo con mayor fuerza. Salteada enfatiza secar Humedad y detener heces sueltas. Jiao Bai Zhu muy tostada enfatiza recepción de Estómago, náusea, plenitud y eructos.')],
    [$qitonifytext('How do Bai Zhu and Fu Ling differ in tonifying Spleen and eliminating Dampness?','¿Cómo se diferencian Bai Zhu y Fu Ling al tonificar Bazo y eliminar Humedad?'),$qitonifytext('Bai Zhu is current-list, warm/bitter, stronger for Spleen Qi and dries Dampness in the Middle. Fu Ling, outside this list, is neutral/bland, gently leaches Dampness through urination and also calms Shen.','Bai Zhu está en la lista, es tibia/amarga, más fuerte para Qi de Bazo y seca Humedad del Medio. Fu Ling, fuera de lista, es neutra/insípida, drena suavemente por orina y calma Shen.')],
    [$qitonifytext('How do Bai Zhu, Shan Yao and Bai Bian Dou differ for Spleen-Qi diarrhea?','¿Cómo se diferencian Bai Zhu, Shan Yao y Bai Bian Dou para diarrea por deficiencia de Bazo?'),$qitonifytext('Bai Zhu dries Dampness and is strongest for Spleen Qi. Shan Yao gently tonifies Qi and Yin and binds chronic leakage. Bai Bian Dou, outside this list, is mild, neither drying nor cloying, and also treats Summer-Heat.','Bai Zhu seca Humedad y es más fuerte para Qi de Bazo. Shan Yao tonifica suavemente Qi-Yin y contiene pérdidas crónicas. Bai Bian Dou, fuera de lista, es suave, ni secante ni empalagosa, y también trata Calor de Verano.')],
    [$qitonifytext('What are the characteristics of Gan Cao?','¿Cuáles son las características de Gan Cao?'),$qitonifytext('Its direct Qi tonification is modest, but it reaches all channels, harmonizes combinations, moderates harshness and relieves spasm. Raw Gan Cao clears toxicity; prepared Zhi Gan Cao more strongly tonifies Middle and Heart Qi. Long or high intake has important fluid, electrolyte and cardiac risks.','Su tonificación directa es modesta, pero alcanza todos los canales, armoniza, modera agresividad y alivia espasmo. Cruda aclara toxicidad; Zhi Gan Cao tonifica más Qi de Medio/Corazón. Uso largo/alto tiene riesgos de líquidos, electrolitos y corazón.')],
];
?>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentythree-foundations"><h4 id="topic-twentythree-foundations"><?php echo s($qitonifytext('Herbs that tonify Qi: general introduction','Hierbas que tonifican Qi: introducción general'));?></h4><p class="single-herbs-guide__section-lead"><?php echo s($qitonifytext('Do not answer “fatigue = Ren Shen.” First prove true deficiency, locate it in Spleen, Lung, Heart or Original Qi, then choose strength and secondary action: raise, secure, dry Dampness, nourish Yin/Blood, relieve pain or harmonize.','No respondas “fatiga = Ren Shen”. Primero demuestra deficiencia verdadera, localízala en Bazo, Pulmón, Corazón o Qi Original y elige fuerza y acción secundaria: elevar, asegurar, secar Humedad, nutrir Yin/Sangre, aliviar dolor o armonizar.'));?></p><p class="single-herbs-guide__scope-note"><strong><?php echo s($qitonifytext('List normalization:','Normalización del listado:'));?></strong> <?php echo s($qitonifytext('Bai Zhu appeared twice in the supplied list and is shown once. “Yi tang” is standardized as Yi Tang. The resulting current category contains eight unique entries.','Bai Zhu apareció dos veces y se muestra una sola vez. “Yi tang” se normaliza como Yi Tang. La categoría actual queda con ocho entradas únicas.'));?></p><div class="single-herbs-guide__decision"><div><strong><?php echo s($qitonifytext('Strong / urgent','Fuerte / urgente'));?></strong><span>Ren Shen · Huang Qi</span></div><div><strong><?php echo s($qitonifytext('Gentle / chronic','Suave / crónico'));?></strong><span>Dang Shen · Da Zao</span></div><div><strong><?php echo s($qitonifytext('Spleen + Dampness','Bazo + Humedad'));?></strong><span>Bai Zhu</span></div><div><strong><?php echo s($qitonifytext('Stabilize / harmonize','Estabilizar / armonizar'));?></strong><span>Shan Yao · Gan Cao · Yi Tang</span></div></div><aside class="single-herbs-guide__memory-path"><p class="single-herbs-guide__memory-line"><?php echo s($qitonifytext('Enter the Qi power station.','Entra a la central eléctrica del Qi.'));?></p><p><?php echo s($qitonifytext('Ren Shen is the main generator; Dang Shen the reliable backup. Huang Qi raises the shield and walls. Bai Zhu dries the damp engine room. Shan Yao braces three floors. Gan Cao is the diplomat at the control board; Da Zao offers the harmonizing snack; Yi Tang pours warm syrup over the cramped kitchen.','Ren Shen es el generador principal; Dang Shen el respaldo confiable. Huang Qi eleva escudo y murallas. Bai Zhu seca la sala de máquinas. Shan Yao sostiene tres pisos. Gan Cao es diplomática del tablero; Da Zao ofrece merienda armonizadora; Yi Tang vierte jarabe tibio sobre la cocina acalambrada.'));?></p></aside><p class="single-herbs-guide__safety"><strong><?php echo s($qitonifytext('Do not tonify what is trapped:','No tonifiques lo atrapado:'));?></strong> <?php echo s($qitonifytext('Unresolved Exterior disease, food stagnation, Phlegm, Dampness, edema or Qi/Blood stasis may worsen when rich sweet herbs are added without treating the obstruction.','Enfermedad Exterior no resuelta, estancamiento alimentario, Flema, Humedad, edema o estasis de Qi/Sangre pueden empeorar si se añaden tónicos dulces sin tratar la obstrucción.'));?></p><ol class="single-herbs-guide__category-herbs"><?php foreach($qitonifyherbs as $h):?><li class="single-herbs-guide__category-herb single-herbs-guide__category-herb--core"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($h['name']);?></strong><em><?php echo s($h['latin']);?></em><span class="single-herbs-guide__category-herb-badge"><?php echo s($qitonifytext('Current category list','Lista vigente de la categoría'));?></span></div><p><?php echo s($h['identity']);?></p></li><?php endforeach;?></ol></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentythree-yang"><h4 id="topic-twentythree-yang"><?php echo s($qitonifytext('Yang comparative fingerprints','Huellas comparativas de Yang'));?></h4><p class="single-herbs-guide__section-lead"><?php echo s($qitonifytext('These are relative study indices—not doses or clinical percentages. Exact values were read from figures 14.1, 14.4 and 14.5; only current-list herbs are graphed.','Son índices relativos de estudio—no dosis ni porcentajes clínicos. Los valores exactos se tomaron de figuras 14.1, 14.4 y 14.5; solo se grafican hierbas de la lista actual.'));?></p><div class="single-herbs-guide__yang-charts"><?php foreach($qitonifycharts as $chart):?><article class="single-herbs-guide__yang-chart"><h5><?php echo s($chart[0]);?></h5><small><?php echo s($chart[1]);?></small><?php foreach($chart[2] as $name=>$value):?><div class="single-herbs-guide__yang-bar"><span><?php echo s($name);?></span><span class="single-herbs-guide__yang-bar-track"><span class="single-herbs-guide__yang-bar-fill" style="width:<?php echo(int)$value;?>%"></span></span><b><?php echo(int)$value;?></b></div><?php endforeach;?></article><?php endforeach;?></div><p class="single-herbs-guide__yang-note"><strong><?php echo s($qitonifytext('Board shortcut:','Atajo Board:'));?></strong> <?php echo s($qitonifytext('Strength alone never decides: Ren Shen rescues, Huang Qi raises/secures, Bai Zhu dries, Shan Yao stabilizes Qi-Yin, Gan Cao harmonizes, and Yi Tang relieves deficiency pain.','La fuerza sola nunca decide: Ren Shen rescata, Huang Qi eleva/asegura, Bai Zhu seca, Shan Yao estabiliza Qi-Yin, Gan Cao armoniza e Yi Tang alivia dolor por deficiencia.'));?></p></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentythree-profiles"><h4 id="topic-twentythree-profiles"><?php echo s($qitonifytext('Individual herb profiles','Perfiles individuales de las hierbas'));?></h4><div class="single-herbs-guide__profiles"><?php foreach($qitonifyherbs as $h):?><details class="single-herbs-guide__profile"<?php echo $h['name']==='Ren Shen'?' open':'';?>><summary><span class="single-herbs-guide__profile-name"><?php echo s($h['name']);?></span><span class="single-herbs-guide__profile-latin"><?php echo s($h['latin']);?></span><span class="single-herbs-guide__profile-meta"><?php echo s($h['properties']);?> · <?php echo s($h['channels']);?></span></summary><div class="single-herbs-guide__profile-body"><dl><dt><?php echo s($qitonifytext('Study dose','Dosis de estudio'));?></dt><dd><?php echo s($h['dose']);?></dd><dt><?php echo s($qitonifytext('Identity','Identidad'));?></dt><dd><?php echo s($h['identity']);?></dd><dt><?php echo s($qitonifytext('Exam clue','Pista de examen'));?></dt><dd><?php echo s($h['clue']);?></dd><dt><?php echo s($qitonifytext('Memory','Memoria'));?></dt><dd class="single-herbs-guide__profile-memory"><?php echo s($h['memory']);?></dd><dt><?php echo s($qitonifytext('Unique fingerprint','Huella única'));?></dt><dd><?php echo s($h['unique']);?></dd><dt><?php echo s($qitonifytext('Formula boundary','Límite de fórmulas'));?></dt><dd class="single-herbs-guide__profile-formulas"><?php if($h['formulas']):foreach($h['formulas'] as $i=>$formula):?><?php if($i):?> · <?php endif;?><?php $path='/study-guide/comparisons/formula-navigator-'.sprintf('%02d',$formula[0]).'-'.$formula[1].($ises?'-es':'').'.html';$url=new moodle_url($path,['from'=>'single-herbs','focus'=>(string)$selected['number']]);?><a href="<?php echo $url->out(false);?>"><strong><?php echo s($formula[2]);?></strong></a> (<?php echo s($formula[3]);?>)<?php endforeach;?> — <?php echo s($qitonifytext('current 63-formula roster.','listado vigente de 63 fórmulas.'));?><?php else:echo s($qitonifytext('No chief or co-chief role in the current 63-formula Board roster.','No tiene papel principal ni coprincipal en el listado Board vigente de 63 fórmulas.'));endif;?></dd><dt><?php echo s($qitonifytext('Safety','Seguridad'));?></dt><dd class="single-herbs-guide__profile-safety"><?php echo s($h['caution']);?></dd></dl></div></details><?php endforeach;?></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentythree-comparisons"><h4 id="topic-twentythree-comparisons"><?php echo s($qitonifytext('High-yield comparisons','Comparaciones de alto rendimiento'));?></h4><div class="single-herbs-guide__comparisons"><?php foreach($qitonifycomparisons as $c):?><?php $url=new moodle_url($ises?$c[1]:$c[0],['from'=>'single-herbs','focus'=>(string)$selected['number']]);?><a class="single-herbs-guide__comparison" href="<?php echo $url->out(false);?>"><strong><?php echo s($c[2]);?></strong><span><?php echo s($c[3]);?></span><small><?php echo s($qitonifytext('Open full comparison →','Abrir comparación completa →'));?></small></a><?php endforeach;?></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentythree-questions"><h4 id="topic-twentythree-questions"><?php echo s($qitonifytext('Yang questions shown in full','Preguntas de Yang mostradas completas'));?></h4><p class="single-herbs-guide__section-lead"><?php echo s($qitonifytext('The first sixteen Chapter 14 questions establish tonic strategy and differentiate this Qi-tonic list. Outside-list herbs are marked in the answers.','Las primeras dieciséis preguntas del capítulo 14 establecen estrategia tónica y diferencian esta lista de Qi. Las hierbas fuera de lista se señalan en las respuestas.'));?></p><div class="single-herbs-guide__yang-deck" data-yang-deck data-card-label="<?php echo s($qitonifytext('Card','Tarjeta'));?>" data-of-label="<?php echo s($qitonifytext('of','de'));?>"><?php foreach($qitonifyquestions as $i=>$q):?><article class="single-herbs-guide__yang-card<?php echo $i===0?' is-active':'';?>" data-yang-card aria-hidden="<?php echo $i===0?'false':'true';?>"><div class="single-herbs-guide__yang-face single-herbs-guide__yang-face--front"><span class="single-herbs-guide__yang-label"><?php echo s($qitonifytext('Question','Pregunta'));?> <?php echo$i+1;?> <?php echo s($qitonifytext('of','de'));?> <?php echo count($qitonifyquestions);?> · Yang, <?php echo s($qitonifytext('Chapter','capítulo'));?> 14</span><p class="single-herbs-guide__yang-question"><?php echo s($q[0]);?></p></div><div class="single-herbs-guide__yang-face single-herbs-guide__yang-face--back"><span class="single-herbs-guide__yang-label"><?php echo s($qitonifytext('Answer','Respuesta'));?> <?php echo$i+1;?></span><p class="single-herbs-guide__yang-answer"><?php echo s($q[1]);?></p></div></article><?php endforeach;?><div class="single-herbs-guide__yang-controls"><button class="single-herbs-guide__yang-control" type="button" data-yang-prev>← <?php echo s($qitonifytext('Previous','Anterior'));?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--flip" type="button" data-yang-flip data-show-label="<?php echo s($qitonifytext('Show answer','Mostrar respuesta'));?>" data-hide-label="<?php echo s($qitonifytext('Show question','Mostrar pregunta'));?>"><?php echo s($qitonifytext('Show answer','Mostrar respuesta'));?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--next" type="button" data-yang-next><?php echo s($qitonifytext('Next','Siguiente'));?> →</button></div><p class="single-herbs-guide__yang-progress" data-yang-progress><?php echo s($qitonifytext('Card','Tarjeta'));?> 1 <?php echo s($qitonifytext('of','de'));?> <?php echo count($qitonifyquestions);?></p></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentythree-recall"><h4 id="topic-twentythree-recall"><?php echo s($qitonifytext('Quick recall','Repaso rápido'));?></h4><div class="single-herbs-guide__recall"><details><summary><?php echo s($qitonifytext('Strongest, fastest Original-Qi rescue?','¿Rescate más fuerte y rápido de Qi Original?'));?></summary><p><strong>Ren Shen.</strong></p></details><details><summary><?php echo s($qitonifytext('Raise prolapse and secure spontaneous sweating?','¿Elevar prolapso y asegurar sudor espontáneo?'));?></summary><p><strong>Huang Qi.</strong></p></details><details><summary><?php echo s($qitonifytext('Chronic gentle substitute—but not for collapse?','¿Sustituta suave crónica—pero no para colapso?'));?></summary><p><strong>Dang Shen.</strong></p></details><details><summary><?php echo s($qitonifytext('Spleen deficiency plus Dampness?','¿Deficiencia de Bazo más Humedad?'));?></summary><p><strong>Bai Zhu.</strong></p></details><details><summary><?php echo s($qitonifytext('Qi–Yin bridge that stabilizes three organs?','¿Puente Qi–Yin que estabiliza tres órganos?'));?></summary><p><strong>Shan Yao.</strong></p></details><details><summary><?php echo s($qitonifytext('Warm syrup for deficiency abdominal pain?','¿Jarabe tibio para dolor abdominal por deficiencia?'));?></summary><p><strong>Yi Tang.</strong></p></details><details><summary><?php echo s($qitonifytext('Broad harmonizer with electrolyte and blood-pressure risk?','¿Armonizador amplio con riesgo electrolítico y de presión arterial?'));?></summary><p><strong>Gan Cao.</strong></p></details></div></section>

